#[test]
fn finished_cli_subagent_without_exchange_does_not_panic_or_create_card() {
    // Issue #881: under CPU starvation an Enter typed into a bootstrapping tab was
    // routed to the agent, the subagent's only request failed with
    // `UpdateTask(TaskNotInitialized)` before an exchange was appended, and the
    // `FinishedSubagent` -> `RestoredReadOnly` rebuild then hit
    // `.expect("Exchange exists.")` in `CLISubagentView::new_with_mode` on the main
    // thread, killing the whole app. The block still carries matching metadata, so
    // the rebuild precondition passes; the card must be skipped instead.
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        // FinishedSubagent triggers sidecar persistence, which needs GlobalResourceHandlesProvider.
        let global_resource_handles = crate::GlobalResourceHandles::mock(&mut app);
        app.add_singleton_model(|_| {
            crate::GlobalResourceHandlesProvider::new(global_resource_handles)
        });

        let task_id = TaskId::new("cli-task-failed-request".to_string());
        let terminal = add_window_with_terminal(&mut app, None);
        let (block_id, conversation_id) = terminal.update(&mut app, |view, ctx| {
            // A conversation with no exchange anywhere: neither the subagent task nor
            // the root task has one, so the BYOP root-task fallback finds nothing too.
            let conversation_id =
                BlocklistAIHistoryModel::handle(ctx).update(ctx, |history_model, ctx| {
                    history_model.start_new_conversation(view.view_id, false, false, ctx)
                });

            let mut model = view.model.lock();
            model.simulate_block("echo failed-request", "");
            let block = model
                .block_list_mut()
                .blocks_mut()
                .iter_mut()
                .find(|block| block.command_to_string() == "echo failed-request")
                .expect("simulated block should exist");
            block.set_agent_interaction_mode(AgentInteractionMetadata::new(
                None,
                conversation_id,
                Some(task_id.clone()),
                None,
                false,
                false,
            ));
            (block.id().clone(), conversation_id)
        });

        terminal.read(&app, |_, ctx| {
            assert!(
                BlocklistAIHistoryModel::as_ref(ctx)
                    .conversation(&conversation_id)
                    .is_some(),
                "the conversation must exist, so the test exercises the missing-exchange \
                 path rather than the missing-conversation one"
            );
            assert!(
                CLISubagentView::initial_exchange(&conversation_id, &task_id, ctx).is_none(),
                "a conversation with no exchange has nothing for a card to open on"
            );
        });

        terminal.update(&mut app, |view, ctx| {
            view.handle_cli_subagent_controller_event(
                view.cli_subagent_controller.clone(),
                &CLISubagentEvent::FinishedSubagent {
                    block_id: block_id.clone(),
                    task_id: task_id.clone(),
                    conversation_id: Some(conversation_id),
                    initial_requested_command_action_id: None,
                },
                ctx,
            );
        });

        terminal.read(&app, |view, _| {
            assert!(
                !view.cli_subagent_views.contains_key(&block_id),
                "FinishedSubagent must not create a read-only card for a conversation \
                 with no exchange"
            );
        });
    });
}

#[test]
fn spawned_cli_subagent_associates_anchor_block_with_conversation() {
    // Issue #799: tagging the agent into a running command never associated the anchor
    // command block's `AgentViewVisibility` with the new conversation. Opening the
    // FullScreen agent view for that conversation later (e.g. from the collapsed
    // summary card shown once the command finishes) relies on `TranscriptScope`
    // filtering, which only shows blocks whose `AgentViewVisibility` names the active
    // conversation (see `Block::should_hide_block`) -- so the pane rendered blank even
    // though the response was fully persisted. The fix associates (and promotes) the
    // anchor block with the conversation at spawn time, the same way a normal
    // Ctrl-Shift-Enter tag-in does for the selected block.
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        // `create_cli_subagent_view`'s live-spawn association code reads
        // `GlobalResourceHandlesProvider` (for the persistence sender it forwards
        // `UpdateBlockAgentViewVisibility` to); same idiom as the other
        // CLI-subagent tests in this file.
        let global_resource_handles = crate::GlobalResourceHandles::mock(&mut app);
        app.add_singleton_model(|_| {
            crate::GlobalResourceHandlesProvider::new(global_resource_handles)
        });

        let conversation_id = AIConversationId::new();
        let task_id = TaskId::new("cli-task-live".to_string());

        let terminal = add_window_with_terminal(&mut app, None);
        let block_id = terminal.update(&mut app, |view, ctx| {
            let block_id = {
                let mut model = view.model.lock();
                model.simulate_block("sleep 90", "");
                model
                    .block_list()
                    .blocks()
                    .iter()
                    .find(|block| block.command_to_string() == "sleep 90")
                    .expect("simulated block should exist")
                    .id()
                    .clone()
            };

            // `create_cli_subagent_view` looks up the task's exchange in the history
            // model and panics if it's missing (`.expect("Exchange exists.")`), so the
            // conversation/task/exchange must be registered there first -- but register
            // it directly via `restore_conversations` rather than going through
            // `restore_conversation_after_view_creation`, which would also insert a
            // *restored* command block carrying a pre-baked `AgentViewVisibility`. The
            // live, freshly simulated block above must keep its plain, unassociated
            // `AgentViewVisibility::Terminal` so the assertion below actually exercises
            // `create_cli_subagent_view`'s own live-spawn association, not a snapshot's.
            let conversation = build_restored_conversation_with_cli_subagent_snapshot_for_test(
                conversation_id,
                block_id.clone(),
                task_id.clone(),
                b"",
            );
            BlocklistAIHistoryModel::handle(ctx).update(ctx, |history_model, ctx| {
                history_model.restore_conversations(view.view_id, vec![conversation], ctx);
            });

            view.handle_cli_subagent_controller_event(
                view.cli_subagent_controller.clone(),
                &CLISubagentEvent::SpawnedSubagent {
                    task_id: task_id.clone(),
                    block_id: block_id.clone(),
                    conversation_id,
                    initial_requested_command_action_id: None,
                },
                ctx,
            );
            block_id
        });

        terminal.read(&app, |view, _| {
            let model = view.model.lock();
            let block = model
                .block_list()
                .block_with_id(&block_id)
                .expect("anchor command block should still exist");
            match block.agent_view_visibility() {
                AgentViewVisibility::Terminal {
                    pending_conversation_ids,
                    conversation_ids,
                } => {
                    assert!(
                        pending_conversation_ids.contains(&conversation_id)
                            || conversation_ids.contains(&conversation_id),
                        "anchor command block should be associated with the spawned \
                         subagent's conversation so the FullScreen agent view can find it"
                    );
                }
                visibility => panic!("expected terminal block visibility, got {visibility:?}"),
            }
        });
    });
}

#[cfg(windows)]
#[test]
fn restored_cli_subagent_windows_ctrl_c_does_not_write_to_pty() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);

        let terminal = add_window_with_terminal(&mut app, None);
        let pty_writes: Rc<RefCell<Vec<Vec<u8>>>> = Rc::new(RefCell::new(Vec::new()));
        let writes = pty_writes.clone();
        app.update(|ctx| {
            ctx.subscribe_to_view(&terminal, move |_, event, _| {
                if let Event::WriteBytesToPty { bytes } = event {
                    writes.borrow_mut().push(bytes.to_vec());
                }
            });
        });

        terminal.update(&mut app, |view, ctx| {
            // Give the Ctrl-C live path an observable side effect: if forwarded, it writes ETX to the PTY.
            view.model
                .lock()
                .simulate_long_running_block("sleep 10", "running");

            view.handle_cli_subagent_view_event(
                view.view_id,
                &CLISubagentViewEvent::WindowsCtrlC,
                false,
                ctx,
            );
        });
        assert!(
            pty_writes.borrow().is_empty(),
            "restored CLI subagent Ctrl-C should not reach the live terminal"
        );

        terminal.update(&mut app, |view, ctx| {
            view.handle_cli_subagent_view_event(
                view.view_id,
                &CLISubagentViewEvent::WindowsCtrlC,
                true,
                ctx,
            );
        });
        assert_eq!(
            pty_writes.borrow().as_slice(),
            &[vec![warp_terminal::model::escape_sequences::C0::ETX]],
            "live CLI subagent Ctrl-C should still forward to the active terminal"
        );
    });
}

/// Test to verify that blocks created through normal execution
/// have the correct local status set
#[test]
fn test_create_new_block_with_local_status() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        let terminal = add_window_with_terminal(&mut app, None);

        // Set up a terminal with a local session
        terminal.update(&mut app, |view, _ctx| {
            let mut model = view.model.lock();

            // Initialize a local session
            model.init_shell(InitShellValue {
                session_id: 0.into(),
                shell: "bash".to_owned(),
                ..Default::default()
            });
            model.bootstrapped(BootstrappedValue {
                shell: "bash".to_owned(),
                ..Default::default()
            });
        });

        assert_eventually!(
            terminal.read(&app, |view, ctx| !view
                .active_block_is_considered_remote(ctx)),
            "Block should be local"
        );

        // No remote blocks should exist
        assert_eventually!(
            terminal.read(&app, |view, _ctx| !view.contains_restored_remote_blocks()),
            "No remote blocks should exist"
        );

        // Update the view's flags
        // view.update_focused_terminal_info(ctx);
        assert_eventually!(
            terminal.read(&app, |view, _ctx| !view.any_session_contains_remote_blocks),
            "No remote blocks should exist"
        );

        // Now test with a remote session
        terminal.update(&mut app, |view, _ctx| {
            let mut model = view.model.lock();

            // Create a new block with a remote session ID and remote_shell
            model.init_shell(InitShellValue {
                session_id: 1.into(),
                shell: "bash".to_owned(),
                user: "user".to_owned(),
                hostname: "remote".to_owned(),
                ..Default::default()
            });
            model.bootstrapped(BootstrappedValue {
                shell: "bash".to_owned(),
                ..Default::default()
            });

            // Create a block in the remote session
            model.simulate_block("echo remote", "remote output");
        });

        // Verify block is non-local (remote)
        assert_eventually!(
            terminal.read(&app, |view, ctx| view
                .active_block_is_considered_remote(ctx)),
            "Block should be non-local (remote)"
        );

        // Remote blocks should be detected
        assert_eventually!(
            terminal.read(&app, |view, _ctx| view.any_session_contains_remote_blocks),
            "Remote blocks should be detected"
        );
    })
}

#[test]
fn submit_cli_agent_rich_input_restores_unlocked_input_config() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        let _agent_view = FeatureFlag::AgentView.override_enabled(true);
        let _cli_agent_rich_input = FeatureFlag::CLIAgentRichInput.override_enabled(true);
        AISettings::handle(&app).update(&mut app, |settings, ctx| {
            let _ = settings
                .auto_dismiss_rich_input_after_submit
                .set_value(true, ctx);
        });

        let terminal = add_window_with_terminal(&mut app, None);

        terminal.update(&mut app, |view, ctx| {
            view.input.update(ctx, |input, ctx| {
                input.ai_input_model().update(ctx, |ai_input, ctx| {
                    ai_input.set_input_config(
                        InputConfig {
                            input_type: InputType::Shell,
                            is_locked: false,
                        },
                        true,
                        ctx,
                    );
                });
            });

            CLIAgentSessionsModel::handle(ctx).update(ctx, |sessions, ctx| {
                sessions.set_session(
                    view.view_id,
                    CLIAgentSession {
                        agent: CLIAgent::Droid,
                        status: CLIAgentSessionStatus::InProgress,
                        session_context: CLIAgentSessionContext::default(),
                        input_state: CLIAgentInputState::Closed,
                        should_auto_toggle_input: false,
                        listener: None,
                        remote_host: None,
                        plugin_version: None,
                        draft_text: None,
                        custom_command_prefix: None,
                        received_rich_notification: false,
                    },
                    ctx,
                );
            });

            view.open_cli_agent_rich_input(CLIAgentInputEntrypoint::FooterButton, ctx);
            assert!(view.has_active_cli_agent_input_session(ctx));

            view.submit_cli_agent_rich_input("hello!".to_owned(), ctx);
            assert!(!view.has_active_cli_agent_input_session(ctx));
        });

        terminal.read(&app, |view, ctx| {
            let input = view.input.as_ref(ctx);
            let ai_input_model = input.ai_input_model().as_ref(ctx);

            assert_eq!(
                ai_input_model.input_config(),
                InputConfig {
                    input_type: InputType::Shell,
                    is_locked: false,
                }
            );
            assert!(input.editor().as_ref(ctx).buffer_text(ctx).is_empty());
        });
    })
}

