#[test]
fn test_retained_line_eviction_shifts_view_state_in_one_step() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        // The eviction notice toast needs the singleton the app registers at startup.
        app.add_singleton_model(|_| crate::ToastStack);

        let terminal = add_window_with_terminal(&mut app, None);
        terminal.update(&mut app, |view, ctx| {
            let protected_id = {
                let mut model = view.model.lock();
                for _ in 0..10 {
                    model.simulate_block("ls", "foo");
                }
                // Tiny budget (floored at the per-block limit, which we also lower) so that
                // everything before the protected block is over budget.
                model.update_max_grid_size(1);
                model.update_max_retained_lines(1);
                model.block_list().blocks()[5].id().clone()
            };
            let id_at = |view: &TerminalView, index: BlockIndex| {
                view.model
                    .lock()
                    .block_list()
                    .block_at(index)
                    .map(|block| block.id().clone())
            };
            let hovered_id = id_at(view, BlockIndex::from(7));
            let selected_id = id_at(view, BlockIndex::from(8));

            // Simulating blocks above did not evict anything: the model never evicts on its own.
            assert!(view.model.lock().block_list().blocks().len() >= 10);

            view.bookmark_block(&BlockIndex::from(5), ctx);
            view.hovered_block_index = Some(BlockIndex::from(7));
            view.mouse_down_block_index = Some(BlockIndex::from(1));
            view.selected_blocks.reset_to_single(BlockIndex::from(8));
            view.hovered_secret = None;

            let evicted = view.evict_retained_blocks(ctx);
            assert!(
                evicted > 0,
                "blocks before the protected one are over budget"
            );
            assert!(evicted <= 5, "must stop at the bookmarked block");

            // The bookmark followed its block.
            let new_bookmark = BlockIndex::from(5 - evicted);
            assert!(view.bookmarked_blocks.contains_key(&new_bookmark));
            assert_eq!(view.bookmarked_blocks.len(), 1);
            assert_eq!(id_at(view, new_bookmark), Some(protected_id));

            // Hover followed its block; a mouse-down on an evicted block was dropped.
            assert_eq!(
                view.hovered_block_index
                    .and_then(|index| id_at(view, index)),
                hovered_id
            );
            assert_eq!(
                view.mouse_down_block_index,
                (1usize).checked_sub(evicted).map(BlockIndex::from)
            );

            // The selection followed its block.
            assert_eq!(
                view.selected_blocks
                    .tail()
                    .and_then(|index| id_at(view, index)),
                selected_id
            );

            // Hover caches that hold old-index positions were invalidated.
            assert!(view.last_hover_fragment_boundary.is_none());
            assert!(!view.has_highlighted_link());
            assert!(view.hovered_secret.is_none());
        });
    })
}

/// #915: the cap must work through the real path -- the setting value reaching the model via the
/// view's settings subscription, then the view's own eviction entry point -- and must count the
/// scrollback history that lives in flat storage, not just the live grid rows.
#[test]
fn test_max_retained_lines_setting_bounds_retained_history() {
    // Shipped builds enable this flag by default (`enabled_features()`); tests start with every
    // flag off, so force it to move a finished block's scrollback into flat storage.
    let _flat = FeatureFlag::MaximizeFlatStorage.override_enabled(true);
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        app.add_singleton_model(|_| crate::ToastStack);

        let terminal = add_window_with_terminal(&mut app, None);
        let output = (0..300)
            .map(|i| format!("line {i}"))
            .collect::<Vec<_>>()
            .join("\r\n");
        terminal.update(&mut app, |view, _| {
            let mut model = view.model.lock();
            for _ in 0..8 {
                model.simulate_block("seq", output.as_str());
            }
            assert!(
                model
                    .block_list()
                    .blocks()
                    .iter()
                    .any(|block| block.flat_storage_lines() > 0),
                "finished output must have scrollback history in flat storage"
            );
        });

        // Setting off (the default): nothing is evicted.
        let before = terminal.read(&app, |view, _| {
            view.model.lock().block_list().blocks().len()
        });
        terminal.update(&mut app, |view, ctx| {
            view.maybe_evict_retained_blocks(ctx);
        });
        let after = terminal.read(&app, |view, _| {
            view.model.lock().block_list().blocks().len()
        });
        assert_eq!(before, after, "setting off must not evict");

        // Turn the cap on through the settings model, as settings.toml / the UI does.
        TerminalSettings::handle(&app).update(&mut app, |settings, ctx| {
            report_if_error!(settings.maximum_grid_size.set_value(100, ctx));
            report_if_error!(settings.max_retained_lines.set_value(800, ctx));
        });
        terminal.update(&mut app, |view, ctx| {
            view.maybe_evict_retained_blocks(ctx);
            let model = view.model.lock();
            let blocks = model.block_list().blocks();
            let total: usize = blocks.iter().map(|b| b.retained_lines()).sum();
            assert!(blocks.len() < before, "old blocks must have been evicted");
            assert!(blocks.len() >= 2, "recent blocks are kept");
            // Eviction stops as soon as the total fits, so dropping one more block would not
            // have been needed: the total is within budget.
            assert!(total <= 800, "retained lines {total} exceed the cap");
            assert!(model.block_list().evicted_total() > 0);
        });
    })
}

#[test]
fn test_stamped_layout_actions_resolve_across_eviction() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        // The eviction notice toast needs the singleton the app registers at startup.
        app.add_singleton_model(|_| crate::ToastStack);

        let terminal = add_window_with_terminal(&mut app, None);
        terminal.update(&mut app, |view, ctx| {
            {
                let mut model = view.model.lock();
                for _ in 0..10 {
                    model.simulate_block("ls", "foo");
                }
                model.update_max_grid_size(1);
                model.update_max_retained_lines(1);
            }
            // Bookmark the block at index 5 (which also protects it from eviction), then capture
            // layout-time stamped indices for it and for the oldest block, as the bookmark and
            // filter buttons do.
            view.bookmark_block(&BlockIndex::from(5), ctx);
            let total_at_layout = view.model.lock().block_list().evicted_total();
            let stamped_bookmarked = StampedBlockIndex::new(BlockIndex::from(5), total_at_layout);
            let stamped_oldest = StampedBlockIndex::new(BlockIndex::zero(), total_at_layout);

            let evicted = view.evict_retained_blocks(ctx);
            assert!(evicted > 0 && evicted <= 5);

            // Before the next layout, the stale stamps still resolve to the right block, and an
            // evicted block resolves to nothing.
            assert_eq!(
                view.resolve_stamped_block_index(stamped_bookmarked),
                Some(BlockIndex::from(5 - evicted))
            );
            assert_eq!(view.resolve_stamped_block_index(stamped_oldest), None);

            // Dispatching the stale action toggles the bookmark off at its shifted index rather
            // than adding a bookmark at the stale one.
            assert_eq!(view.bookmarked_blocks.len(), 1);
            view.handle_action(&TerminalAction::BookmarkBlock(stamped_bookmarked), ctx);
            assert!(view.bookmarked_blocks.is_empty());

            // An action for an evicted block is a no-op.
            view.handle_action(&TerminalAction::BookmarkBlock(stamped_oldest), ctx);
            assert!(view.bookmarked_blocks.is_empty());
        });
    })
}

/// #889: the Ask AI and block-overflow-menu actions are stamped at layout like the bookmark and
/// filter actions. Dispatched after eviction they resolve to the shifted block, or do nothing
/// when that block was evicted.
#[test]
fn test_stamped_ask_ai_and_overflow_menu_actions_resolve_across_eviction() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        // The eviction notice toast needs the singleton the app registers at startup.
        app.add_singleton_model(|_| crate::ToastStack);

        let terminal = add_window_with_terminal(&mut app, None);
        terminal.update(&mut app, |view, ctx| {
            {
                let mut model = view.model.lock();
                for _ in 0..10 {
                    model.simulate_block("ls", "foo");
                }
                model.update_max_grid_size(1);
                model.update_max_retained_lines(1);
            }
            // Bookmarking protects block 5 from eviction, so it survives at a shifted index.
            view.bookmark_block(&BlockIndex::from(5), ctx);
            let total_at_layout = view.model.lock().block_list().evicted_total();
            let stamped_kept = StampedBlockIndex::new(BlockIndex::from(5), total_at_layout);
            let stamped_oldest = StampedBlockIndex::new(BlockIndex::zero(), total_at_layout);

            let evicted = view.evict_retained_blocks(ctx);
            assert!(evicted > 0 && evicted <= 5);
            let shifted = BlockIndex::from(5 - evicted);

            // The overflow menu for an evicted block does nothing: no selection, no menu.
            view.handle_action(
                &TerminalAction::BlockListContextMenu(BlockListMenuSource::BlockOverflowButton {
                    block_index: stamped_oldest,
                }),
                ctx,
            );
            assert!(view.selected_blocks.tail().is_none());
            assert!(!view.is_context_menu_open());

            // Ask AI for an evicted block is a no-op too.
            view.handle_action(
                &TerminalAction::AskAIAssistant {
                    block_index: stamped_oldest,
                },
                ctx,
            );
            assert!(view.selected_blocks.tail().is_none());

            // The overflow menu for a surviving block targets its shifted index, not the stale one.
            view.handle_action(
                &TerminalAction::BlockListContextMenu(BlockListMenuSource::BlockOverflowButton {
                    block_index: stamped_kept,
                }),
                ctx,
            );
            assert!(view.selected_blocks.is_selected(shifted));
            assert!(!view.selected_blocks.is_selected(BlockIndex::from(5)));
        });
    })
}

