#[test]
fn agent_footer_updates_chip_groups_when_side_assignment_changes() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        let _agent_view_guard = FeatureFlag::AgentView.override_enabled(true);

        let terminal = add_window_with_terminal(&mut app, None);
        // The agent footer's chips only run while the agent view is actually
        // active, so this test has to enter it before asserting on chip groups.
        terminal.update(&mut app, |view, ctx| {
            view.agent_view_controller().update(ctx, |controller, ctx| {
                controller
                    .try_enter_agent_view(
                        None,
                        AgentViewEntryOrigin::Input {
                            was_prompt_autodetected: false,
                        },
                        ctx,
                    )
                    .expect("Should be able to enter agent view");
            });
        });

        terminal.update(&mut app, |view, ctx| {
            let model = view.model.lock();
            view.current_prompt.update(ctx, |prompt, ctx| {
                let PromptType::Dynamic { prompt } = prompt else {
                    return;
                };
                prompt.update(ctx, |prompt, ctx| {
                    prompt.update_context(model.block_list().active_block(), ctx);
                });
            });
        });

        SessionSettings::handle(&app).update(&mut app, |settings, ctx| {
            let _ = settings.agent_footer_chip_selection.set_value(
                AgentToolbarChipSelection::Custom {
                    left: vec![AgentToolbarItemKind::ContextChip(ContextChipKind::Time12)],
                    right: vec![AgentToolbarItemKind::ContextChip(ContextChipKind::Time24)],
                },
                ctx,
            );
        });

        assert_eventually!(
            terminal.read(&app, |view, ctx| {
                view.input().as_ref(ctx).agent_footer_chip_kinds(ctx)
                    == (vec![ContextChipKind::Time12], vec![ContextChipKind::Time24])
            }),
            "Agent footer should render separate left and right chip groups"
        );

        SessionSettings::handle(&app).update(&mut app, |settings, ctx| {
            let _ = settings.agent_footer_chip_selection.set_value(
                AgentToolbarChipSelection::Custom {
                    left: vec![
                        AgentToolbarItemKind::ContextChip(ContextChipKind::Time12),
                        AgentToolbarItemKind::ContextChip(ContextChipKind::Time24),
                    ],
                    right: vec![],
                },
                ctx,
            );
        });

        assert_eventually!(
            terminal.read(&app, |view, ctx| {
                view.input().as_ref(ctx).agent_footer_chip_kinds(ctx)
                    == (
                        vec![ContextChipKind::Time12, ContextChipKind::Time24],
                        vec![],
                    )
            }),
            "Agent footer should update when a chip moves between sides without changing overall chip order"
        );
    })
}

#[test]
fn test_link_at_range_trims_zero_width_spaces() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        let terminal = add_window_with_terminal(&mut app, None);

        // NOTE: this has two zero-width spaces, one after the '(', and one before the ')'
        let input_url = "(\u{200b}https://warp.dev\u{200b})";
        // NOTE: the final character in this string is a zero-width space
        let non_escaped_url = "https://warp.dev\u{200b}";
        let escaped_url = "https://warp.dev";

        terminal.update(&mut app, |view, _ctx| {
            view.model.lock().simulate_block(
                r"printf '(%bhttps://warp.dev%b)\n' '\U200b' '\U200b'",
                input_url,
            );
        });

        terminal.read(&app, |view, ctx| {
            let model = view.model.lock();

            let block = view
                .viewport_state(model.block_list(), InputMode::PinnedToBottom, ctx)
                .iter()
                .next()
                .expect("blocklist should have at least one item");

            let point = WithinModel::BlockList(WithinBlock::new(
                // I picked the point 0, 4 b/c it seemed to work. It's not clear to me
                // why 4 works when numbers like 9 do not. Either way, this is just to
                // get the actual url out (passing 9 fails on url_at_point), and does
                // not matter for testing link_at_range.
                Point::new(0, 4),
                block.block_index.expect("block index should exist"),
                crate::terminal::GridType::Output,
            ));

            let url = model
                .url_at_point(&point)
                .expect("url at the designated point should exist");

            // Assert that string_at_range preserves the ZW Space
            assert_eq!(
                model.string_at_range(&url, RespectObfuscatedSecrets::No),
                non_escaped_url
            );

            // Assert that link_at_range removes the ZW Space
            assert_eq!(
                model.link_at_range(&url, RespectObfuscatedSecrets::No),
                escaped_url
            );
        });
    })
}

#[test]
fn test_scroll_position_doesnt_change_when_block_finished() {
    use futures_lite::StreamExt;

    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        let terminal = add_window_with_terminal(&mut app, None);

        // The completed event carries only the block's metadata (no output bytes: persistence
        // reads those off the UI thread), so the long-running block is told apart by its id.
        let long_running_block_id: Rc<RefCell<Option<BlockId>>> = Rc::new(RefCell::new(None));
        let (tx, rx) = async_channel::bounded(1);
        app.update(|ctx| {
            let long_running_block_id = long_running_block_id.clone();
            ctx.subscribe_to_view(&terminal, move |_, event, _| {
                if let Event::BlockCompleted { block, .. } = event {
                    if long_running_block_id.borrow().as_ref() == Some(&block.id) {
                        tx.try_send(()).expect("Can send over channel");
                    }
                }
            });
        });

        let scroll_position_before_finished = terminal.update(&mut app, |view, ctx| {
            // Finish a lengthy block.
            view.model.lock().simulate_block("ls", &"\n".repeat(1000));
            assert!(view.is_vertically_scrollable(ctx));
            assert_eq!(
                view.scroll_position(),
                ScrollPosition::FollowsBottomOfMostRecentBlock
            );

            // Start long-running block.
            view.model.lock().simulate_long_running_block("", "lr");

            // Before the block is finished, scroll up.
            view.scroll(1.0.into_lines(), ctx);
            let scroll_position_before_finished = view.scroll_position();
            assert!(matches!(
                scroll_position_before_finished,
                ScrollPosition::FixedAtPosition { .. }
            ));

            // Finish the block.
            *long_running_block_id.borrow_mut() =
                Some(view.model.lock().block_list().active_block().id().clone());
            view.model.lock().finish_block();

            scroll_position_before_finished
        });

        // Wait until the terminal view acknowledges the block as completed.
        assert!(pin!(rx).next().await.is_some());

        // Make sure the scroll position is unchanged when the block finishes.
        terminal.read(&app, |view, _| {
            let scroll_position_after_finished = view.scroll_position();
            assert_eq!(
                scroll_position_before_finished,
                scroll_position_after_finished
            );
        });
    })
}

#[test]
fn inline_agent_view_exits_when_tagged_in_long_running_command_is_tagged_out() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        let _agent_view_guard = FeatureFlag::AgentView.override_enabled(true);

        let terminal = add_window_with_terminal(&mut app, None);

        terminal.update(&mut app, |view, ctx| {
            {
                let mut model = view.model.lock();
                model.init_shell(InitShellValue {
                    session_id: 0.into(),
                    shell: "zsh".to_owned(),
                    ..Default::default()
                });
                model.bootstrapped(BootstrappedValue {
                    shell: "zsh".to_owned(),
                    ..Default::default()
                });
                model.simulate_long_running_block("sleep 10", "running");
            }

            view.agent_view_controller().update(ctx, |controller, ctx| {
                controller
                    .try_enter_inline_agent_view(
                        None,
                        AgentViewEntryOrigin::LongRunningCommand,
                        ctx,
                    )
                    .expect("should enter inline agent view for a tagged-in command");
            });
            view.model
                .lock()
                .block_list_mut()
                .active_block_mut()
                .set_is_agent_tagged_in(true);

            assert!(view.agent_view_controller().as_ref(ctx).is_inline());
            assert!(
                view.model
                    .lock()
                    .block_list()
                    .active_block()
                    .is_agent_tagged_in()
            );

            let model = view.model.lock();
            assert!(view.is_input_box_visible(&model, ctx));
            drop(model);

            view.handle_action(&TerminalAction::SetInputModeTerminal, ctx);

            assert!(!view.agent_view_controller().as_ref(ctx).is_active());
            let model = view.model.lock();
            let active_block = model.block_list().active_block();
            assert!(!active_block.is_agent_tagged_in());
            assert!(!view.is_input_box_visible(&model, ctx));
        });
    })
}

#[test]
fn inline_agent_view_persists_across_transfer_takeover_for_monitored_long_running_command() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        let _agent_view_guard = FeatureFlag::AgentView.override_enabled(true);

        let terminal = add_window_with_terminal(&mut app, None);

        terminal.update(&mut app, |view, ctx| {
            {
                let mut model = view.model.lock();
                model.init_shell(InitShellValue {
                    session_id: 0.into(),
                    shell: "zsh".to_owned(),
                    ..Default::default()
                });
                model.bootstrapped(BootstrappedValue {
                    shell: "zsh".to_owned(),
                    ..Default::default()
                });
                model.simulate_long_running_block("ssh localhost", "Password:");
            }

            let conversation_id = view.agent_view_controller().update(ctx, |controller, ctx| {
                controller
                    .try_enter_inline_agent_view(
                        None,
                        AgentViewEntryOrigin::LongRunningCommand,
                        ctx,
                    )
                    .expect("inline agent view should create a conversation")
            });
            view.model
                .lock()
                .block_list_mut()
                .active_block_mut()
                .set_is_agent_tagged_in(true);

            let task_id = TaskId::new("test-task".to_owned());
            view.model
                .lock()
                .block_list_mut()
                .active_block_mut()
                .set_agent_interaction_mode_for_agent_monitored_command(&task_id, conversation_id)
                .expect("tagged-in command should transition to agent-monitored");

            assert!(view.agent_view_controller().as_ref(ctx).is_inline());

            let model = view.model.lock();
            assert!(model.block_list().active_block().is_agent_in_control());
            assert!(view.is_input_box_visible(&model, ctx));
            drop(model);

            view.cli_subagent_controller.update(ctx, |controller, ctx| {
                controller.switch_control_to_user(
                    UserTakeOverReason::TransferFromAgent {
                        reason: "Enter your password".to_owned(),
                    },
                    ctx,
                );
            });

            assert!(view.agent_view_controller().as_ref(ctx).is_inline());
            let model = view.model.lock();
            let active_block = model.block_list().active_block();
            assert!(active_block.is_eligible_for_agent_handoff());
            assert!(!view.is_input_box_visible(&model, ctx));
            drop(model);

            view.cli_subagent_controller.update(ctx, |controller, ctx| {
                controller.handoff_active_command_control_to_agent(ctx);
            });

            assert!(view.agent_view_controller().as_ref(ctx).is_inline());
            let model = view.model.lock();
            let active_block = model.block_list().active_block();
            assert!(active_block.is_agent_in_control());
            assert!(view.is_input_box_visible(&model, ctx));
        });
    })
}

/// Ported from Warp (`completed_user_controlled_lrc_resumes_when_not_suppressed`):
/// a Ctrl-C takeover (Stop) with `should_auto_resume: true` resumes the
/// conversation once the monitored command completes.
#[test]
fn completed_user_controlled_lrc_resumes_when_not_suppressed() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        let _agent_view_guard = FeatureFlag::AgentView.override_enabled(true);

        let terminal = add_window_with_terminal(&mut app, None);
        // The auto-resume path persists a subagent sidecar, which needs
        // GlobalResourceHandlesProvider registered.
        let global_resource_handles = crate::GlobalResourceHandles::mock(&mut app);
        app.add_singleton_model(|_| {
            crate::GlobalResourceHandlesProvider::new(global_resource_handles)
        });
        terminal.update(&mut app, |view, ctx| {
            let conversation_id = BlocklistAIHistoryModel::handle(ctx)
                .update(ctx, |history, ctx| {
                    history.start_new_conversation(view.view_id, false, false, ctx)
                });

            view.model
                .lock()
                .simulate_long_running_block("sleep 20", "running");
            let task_id = TaskId::new("test-cli-subagent".to_owned());
            let block_id = {
                let mut model = view.model.lock();
                let active_block = model.block_list_mut().active_block_mut();
                active_block.set_agent_interaction_mode_for_requested_command(
                    AIAgentActionId::from("requested-command".to_owned()),
                    Some(task_id.clone()),
                    conversation_id,
                );
                active_block
                    .set_agent_interaction_mode_for_agent_monitored_command(
                        &task_id,
                        conversation_id,
                    )
                    .expect("command should become agent monitored");
                active_block
                    .take_over_control_for_user(UserTakeOverReason::Stop {
                        should_auto_resume: true,
                    })
                    .expect("user takeover should succeed");
                active_block.id().clone()
            };

            assert!(
                !view
                    .ai_controller
                    .as_ref(ctx)
                    .has_active_stream_for_conversation(conversation_id, ctx)
            );

            view.on_user_block_completed(&block_id, ctx);

            // A Ctrl-C takeover (Stop) without an explicit teardown should resume
            // the conversation once the command completes.
            assert!(
                view.ai_controller
                    .as_ref(ctx)
                    .has_active_stream_for_conversation(conversation_id, ctx)
            );
        });
    })
}

/// Ported from Warp (`completed_user_controlled_lrc_skips_resume_when_suppressed`):
/// a teardown-style takeover (rewind / stop, `should_auto_resume: false`) does
/// NOT resume when the command completes. The fork's teardown method is
/// `set_user_control_with_stop_reason` (Warp: `set_user_control_for_teardown`).
#[test]
fn completed_user_controlled_lrc_skips_resume_when_suppressed() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        let _agent_view_guard = FeatureFlag::AgentView.override_enabled(true);

        let terminal = add_window_with_terminal(&mut app, None);
        terminal.update(&mut app, |view, ctx| {
            let conversation_id = BlocklistAIHistoryModel::handle(ctx)
                .update(ctx, |history, ctx| {
                    history.start_new_conversation(view.view_id, false, false, ctx)
                });

            view.model
                .lock()
                .simulate_long_running_block("sleep 20", "running");
            let task_id = TaskId::new("test-cli-subagent".to_owned());
            let block_id = {
                let mut model = view.model.lock();
                let active_block = model.block_list_mut().active_block_mut();
                active_block.set_agent_interaction_mode_for_requested_command(
                    AIAgentActionId::from("requested-command".to_owned()),
                    Some(task_id.clone()),
                    conversation_id,
                );
                active_block
                    .set_agent_interaction_mode_for_agent_monitored_command(
                        &task_id,
                        conversation_id,
                    )
                    .expect("command should become agent monitored");
                // Mirrors rewind / stop tearing down the conversation.
                active_block.set_user_control_with_stop_reason();
                active_block.id().clone()
            };

            view.on_user_block_completed(&block_id, ctx);

            assert!(
                !view
                    .ai_controller
                    .as_ref(ctx)
                    .has_active_stream_for_conversation(conversation_id, ctx)
            );
        });
    })
}

/// jwp2987/phosphor#753: an agent-requested command on the warpify path (`ssh`, `docker run`,
/// ...) is finished by `TerminalModel::blocks::reinit_shell` before it ever produces the
/// `LongRunningCommandSnapshot` the BYOP LRC monitor fallback needs to install a control state
/// -- so `long_running_control_state` stays `None` for the block's whole life, exactly the
/// state `set_agent_interaction_mode_for_requested_command` leaves it in here (no
/// `set_agent_interaction_mode_for_agent_monitored_command` call, unlike the sibling tests
/// above). A `PendingLrcAutoQueue` row filed while that command looked "in flight" would
/// otherwise never unlock: that unlock is normally driven exclusively by a CLI subagent
/// finishing, and no subagent is ever created for a block that never got a control state.
/// `on_user_block_completed` must release it directly instead.
#[test]
fn finished_agent_command_with_no_control_state_unlocks_pending_lrc_queue() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);

        let terminal = add_window_with_terminal(&mut app, None);
        terminal.update(&mut app, |view, ctx| {
            let conversation_id = BlocklistAIHistoryModel::handle(ctx)
                .update(ctx, |history, ctx| {
                    history.start_new_conversation(view.view_id, false, false, ctx)
                });

            view.model
                .lock()
                .simulate_long_running_block("ssh build-box", "");
            let block_id = {
                let mut model = view.model.lock();
                let active_block = model.block_list_mut().active_block_mut();
                // No subagent task, and no `set_agent_interaction_mode_for_agent_monitored_command`
                // call -- this block never gets upgraded, exactly the warpify fast path.
                active_block.set_agent_interaction_mode_for_requested_command(
                    AIAgentActionId::from("requested-command".to_owned()),
                    None,
                    conversation_id,
                );
                active_block.id().clone()
            };

            let query_id = QueuedQueryModel::handle(ctx).update(ctx, |model, ctx| {
                model.append(
                    conversation_id,
                    QueuedQuery::new(
                        "queued while ssh was starting".to_owned(),
                        QueuedQueryOrigin::PendingLrcAutoQueue,
                    ),
                    ctx,
                )
            });

            view.on_user_block_completed(&block_id, ctx);

            let origin = QueuedQueryModel::as_ref(ctx)
                .queue(conversation_id)
                .iter()
                .find(|row| row.id() == query_id)
                .map(|row| row.origin());
            assert_eq!(
                origin,
                Some(QueuedQueryOrigin::LrcAutoQueue),
                "a PendingLrcAutoQueue row must unlock once its command's block completes, even \
                 though no CLI subagent was ever created for it"
            );

            // Unlocking must not itself spin up a subagent -- this is a plain queue release, not
            // a BYOP upgrade.
            assert!(
                !BlocklistAIHistoryModel::as_ref(ctx)
                    .conversation(&conversation_id)
                    .is_some_and(|conversation| conversation.has_active_subagent()),
                "unlocking the queue must not create a CLI subagent as a side effect"
            );
        });
    })
}

/// The counterpart to the test above: a block that *did* get upgraded to agent-monitored (a
/// real subagent task, via `set_agent_interaction_mode_for_agent_monitored_command`, the same
/// setup the pre-existing `completed_user_controlled_lrc_resumes_when_not_suppressed` test
/// above uses) must be left to the existing `FinishedSubagent` / `deliver_queued_prompts_after_
/// subagent_finished` unlock path. `on_user_block_completed`'s new check is gated on
/// `long_running_control_state().is_none()` specifically so it never touches this case; a
/// `PendingLrcAutoQueue` row would not normally still be present here (the real snapshot that
/// triggered the upgrade already unlocks it), but this pins that the new check does not
/// spuriously fire for a monitored block regardless.
#[test]
fn finished_agent_monitored_command_leaves_pending_lrc_queue_for_the_existing_path() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);

        let terminal = add_window_with_terminal(&mut app, None);
        // The agent-monitored path persists a subagent sidecar, which needs
        // GlobalResourceHandlesProvider registered (same idiom as the sibling test above).
        let global_resource_handles = crate::GlobalResourceHandles::mock(&mut app);
        app.add_singleton_model(|_| {
            crate::GlobalResourceHandlesProvider::new(global_resource_handles)
        });
        terminal.update(&mut app, |view, ctx| {
            let conversation_id = BlocklistAIHistoryModel::handle(ctx)
                .update(ctx, |history, ctx| {
                    history.start_new_conversation(view.view_id, false, false, ctx)
                });

            view.model
                .lock()
                .simulate_long_running_block("sleep 20", "running");
            let task_id = TaskId::new("test-cli-subagent".to_owned());
            let block_id = {
                let mut model = view.model.lock();
                let active_block = model.block_list_mut().active_block_mut();
                active_block.set_agent_interaction_mode_for_requested_command(
                    AIAgentActionId::from("requested-command".to_owned()),
                    Some(task_id.clone()),
                    conversation_id,
                );
                active_block
                    .set_agent_interaction_mode_for_agent_monitored_command(
                        &task_id,
                        conversation_id,
                    )
                    .expect("command should become agent monitored");
                active_block.id().clone()
            };

            let query_id = QueuedQueryModel::handle(ctx).update(ctx, |model, ctx| {
                model.append(
                    conversation_id,
                    QueuedQuery::new(
                        "queued while the monitored command ran".to_owned(),
                        QueuedQueryOrigin::PendingLrcAutoQueue,
                    ),
                    ctx,
                )
            });

            view.on_user_block_completed(&block_id, ctx);

            let origin = QueuedQueryModel::as_ref(ctx)
                .queue(conversation_id)
                .iter()
                .find(|row| row.id() == query_id)
                .map(|row| row.origin());
            assert_eq!(
                origin,
                Some(QueuedQueryOrigin::PendingLrcAutoQueue),
                "a monitored block's completion must not be the thing that unlocks the queue -- \
                 that stays the CLI subagent's own FinishedSubagent path"
            );
        });
    })
}

