fn single_general_review_comment(content: &str) -> crate::ai::agent::AgentReviewCommentBatch {
    crate::ai::agent::AgentReviewCommentBatch {
        comments: vec![crate::code_review::comments::AttachedReviewComment {
            id: Default::default(),
            content: content.to_string(),
            target: crate::code_review::comments::AttachedReviewCommentTarget::General,
            last_update_time: chrono::Local::now(),
            base: None,
            head: None,
            outdated: false,
            origin: crate::code_review::comments::CommentOrigin::Native,
        }],
        diff_set: std::collections::HashMap::new(),
    }
}

fn set_phosphor_tui_session(view: &mut TerminalView, ctx: &mut ViewContext<TerminalView>) {
    view.model.lock().simulate_long_running_block("warp", "");
    assert_eq!(
        CLIAgent::detect("warp", None, None, ctx),
        Some(CLIAgent::PhosphorTui)
    );

    CLIAgentSessionsModel::handle(ctx).update(ctx, |sessions, ctx| {
        sessions.set_session(
            view.view_id,
            CLIAgentSession {
                agent: CLIAgent::PhosphorTui,
                status: CLIAgentSessionStatus::InProgress,
                session_context: CLIAgentSessionContext::default(),
                input_state: CLIAgentInputState::Closed,
                should_auto_toggle_input: false,
                listener: None,
                remote_host: None,
                plugin_version: None,
                draft_text: None,
                custom_command_prefix: None,
                received_rich_notification: false,
            },
            ctx,
        );
    });
}

/// Ported from the pinned oracle's `warp_tui_listener_does_not_auto_open_rich_input`.
///
/// The TUI now registers a real `CLIAgentSessionListener` like any other
/// plugin-backed agent, so the thing that keeps the GUI's rich input from
/// opening on top of it is `supports_cli_agent_footer()`, not the absence of a
/// listener. This asserts both halves: the listener exists, and the auto-open
/// still doesn't fire.
#[test]
fn phosphor_tui_listener_does_not_auto_open_rich_input() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        AISettings::handle(&app).update(&mut app, |settings, ctx| {
            let _ = settings
                .auto_open_rich_input_on_cli_agent_start
                .set_value(true, ctx);
        });

        let terminal = add_window_with_terminal(&mut app, None);
        terminal.update(&mut app, |view, ctx| {
            view.handle_cli_agent_notification(
                Some(CLI_AGENT_NOTIFICATION_SENTINEL),
                r#"{"v":1,"agent":"warp-tui","event":"session_start"}"#,
                ctx,
            );
        });

        terminal.read(&app, |view, ctx| {
            let session = CLIAgentSessionsModel::as_ref(ctx)
                .session(view.view_id)
                .expect("Phosphor TUI session should be registered");
            assert!(session.listener.is_some());
            assert!(!session.should_auto_toggle_input);
            assert!(!view.has_active_cli_agent_input_session(ctx));
        });
    });
}

