// ── Password-prompt polling must not arm on warpify-compatible subshells (#7) ──
//
// Subshell launches are handled by the warpification path, not by a normal
// command block, so arming the poller for them produces a spurious "needs
// attention" notification when the user navigates away.
#[cfg(unix)]
#[test]
fn password_prompt_polling_is_suppressed_for_warpify_compatible_subshells() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        let (_window_id, terminal) = add_window_with_id_and_terminal(&mut app, None);

        terminal.update(&mut app, |view, ctx| {
            for command in [
                "bash",
                "/bin/zsh",
                "docker run -it ubuntu bash",
                "aws-vault exec prod",
            ] {
                assert!(
                    !view.would_emit_block_started_for_password_prompt_polling(command, ctx),
                    "{command} is a warpify-compatible subshell; the poller must not arm"
                );
            }

            for command in ["sudo apt update", "git push", "ls -la"] {
                assert!(
                    view.would_emit_block_started_for_password_prompt_polling(command, ctx),
                    "{command} is an ordinary command; the poller must still arm"
                );
            }
        });
    })
}

// ── Agent commands must not wedge on interactive prompts (#673) ──
//
// The subshell filter above exists for the user's own warpify-compatible
// commands. `ssh <host>` is deliberately not one of them (only the native
// per-host extension-install path handles a literal `ssh`, so it always
// falls through `would_emit_block_started_for_password_prompt_polling` --
// see `password_prompt_polling_is_suppressed_for_warpify_compatible_subshells`
// above, which is careful to leave `ssh` out of the suppressed list). A
// `docker run ... bash` subshell *is* filtered, so it is the case where the
// agent-driving check has to win over the filter for the agent's password
// prompt to be seen at all.
#[cfg(unix)]
#[test]
fn agent_run_subshell_command_still_arms_password_prompt_polling() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        let (_window_id, terminal) = add_window_with_id_and_terminal(&mut app, None);

        terminal.update(&mut app, |view, ctx| {
            let command = "docker run -it ubuntu bash";
            view.model
                .lock()
                .simulate_long_running_block(command, "Password: ");
            assert!(
                !view.should_start_password_prompt_polling(command, ctx),
                "the user's own subshell command must stay suppressed by the subshell filter"
            );

            let conversation_id = BlocklistAIHistoryModel::handle(ctx)
                .update(ctx, |history, ctx| {
                    history.start_new_conversation(view.view_id, false, false, ctx)
                });
            view.model
                .lock()
                .block_list_mut()
                .active_block_mut()
                .set_agent_interaction_mode_for_requested_command(
                    AIAgentActionId::from("agent-docker".to_owned()),
                    None,
                    conversation_id,
                );

            assert!(
                !view.would_emit_block_started_for_password_prompt_polling(command, ctx),
                "the filter itself is unchanged"
            );
            assert!(
                view.should_start_password_prompt_polling(command, ctx),
                "an agent-run subshell command must be polled, or its password prompt hangs for 30 minutes"
            );
        });
    })
}

/// A `[y/N]` prompt leaves echo on, so termios cannot see it. For a
/// `wait_until_completion` agent command it is handed to the user; for any other
/// agent command the agent gets snapshots and can answer it itself, so it is left
/// alone.
#[cfg(unix)]
#[test]
fn agent_command_stalled_on_confirmation_prompt_is_handed_to_user() {
    App::test((), |mut app| async move {
        initialize_app_for_terminal_view(&mut app);
        let (_window_id, terminal) = add_window_with_id_and_terminal(&mut app, None);

        terminal.update(&mut app, |view, ctx| {
            let action_id = AIAgentActionId::from("agent-apt".to_owned());
            let conversation_id = BlocklistAIHistoryModel::handle(ctx)
                .update(ctx, |history, ctx| {
                    history.start_new_conversation(view.view_id, false, false, ctx)
                });
            {
                let mut model = view.model.lock();
                model.simulate_long_running_block(
                    "sudo apt remove foo",
                    "Removing foo\r\nDo you want to continue? [Y/n] ",
                );
                model
                    .block_list_mut()
                    .active_block_mut()
                    .set_agent_interaction_mode_for_requested_command(
                        action_id.clone(),
                        None,
                        conversation_id,
                    );
            }

            assert_eq!(
                view.pending_interactive_prompt(ctx),
                None,
                "an agent polling with snapshots can answer the prompt itself"
            );

            view.ai_action_model
                .as_ref(ctx)
                .shell_command_executor(ctx)
                .update(ctx, |executor, _| {
                    executor.mark_awaiting_completion_for_test(action_id.clone());
                });
            let prompt = view
                .pending_interactive_prompt(ctx)
                .expect("a wait_until_completion command on a [Y/n] prompt is stalled");
            assert!(
                prompt.text.contains("[Y/n]"),
                "unexpected prompt text: {prompt:?}"
            );

            view.on_stalled_interactive_prompt(ctx);
            let control_state = view
                .model
                .lock()
                .block_list()
                .active_block()
                .long_running_control_state()
                .cloned();
            assert_eq!(
                control_state,
                Some(LongRunningCommandControlState::User {
                    reason: UserTakeOverReason::BlockedOnInput,
                })
            );
            assert!(
                view.keeps_polling_after_prompt(),
                "an agent command keeps polling so a later prompt is caught too"
            );

            // While the user holds the command no candidate is reported, which is what
            // re-arms the manager's `PromptDetector`...
            assert_eq!(view.pending_interactive_prompt(ctx), None);

            // ...so once control comes back to the agent, a prompt is reported again.
            view.model
                .lock()
                .block_list_mut()
                .active_block_mut()
                .handoff_control_to_agent()
                .expect("hand-back from BlockedOnInput should succeed");
            assert!(view.pending_interactive_prompt(ctx).is_some());
        });
    })
}

// ---------------------------------------------------------------------------
// Depth-aware agent-view back button.
//
// Ported from the pinned oracle's `app/src/terminal/view_tests.rs`
// (`back_button_label_names_the_direct_parent_at_depth`,
// `back_button_label_resolves_token_only_parent_linkage`). The fork's test
// file is `view_test.rs`, and `start_new_conversation` takes one fewer flag
// here; the labels come from fluent (`terminal-agent-header-*`), which
// `initialize_history_persistence_for_tests` pins to English.
// ---------------------------------------------------------------------------

#[test]
fn back_button_label_names_the_direct_parent_at_depth() {
    App::test((), |mut app| async move {
        crate::test_util::settings::initialize_history_persistence_for_tests(&mut app);
        let terminal_view_id = EntityId::new();
        let history_model = app.add_singleton_model(|_| BlocklistAIHistoryModel::new_for_test());
        let (root_id, mid_id, grandchild_id) = history_model.update(&mut app, |history, ctx| {
            let root_id = history.start_new_conversation(terminal_view_id, false, false, ctx);
            let mid_id = history.start_new_child_conversation(
                terminal_view_id,
                "api-refactor".to_string(),
                root_id,
                None,
                ctx,
            );
            let grandchild_id = history.start_new_child_conversation(
                terminal_view_id,
                "grandchild".to_string(),
                mid_id,
                None,
                ctx,
            );
            (root_id, mid_id, grandchild_id)
        });

        // A nested parent whose agent name is empty falls back to the
        // generic wording instead of rendering "for ".
        let (unnamed_mid_id, nested_under_unnamed_id) =
            history_model.update(&mut app, |history, ctx| {
                let unnamed_mid_id = history.start_new_child_conversation(
                    terminal_view_id,
                    String::new(),
                    root_id,
                    None,
                    ctx,
                );
                let nested_id = history.start_new_child_conversation(
                    terminal_view_id,
                    "nested".to_string(),
                    unnamed_mid_id,
                    None,
                    ctx,
                );
                (unnamed_mid_id, nested_id)
            });

        history_model.read(&app, |history, _| {
            assert_eq!(agent_view_back_button_label(history, None), "for terminal");
            assert_eq!(
                agent_view_back_button_label(history, Some(root_id)),
                "for terminal",
            );
            assert_eq!(
                agent_view_back_button_label(history, Some(mid_id)),
                "for Orchestrator",
            );
            assert_eq!(
                agent_view_back_button_label(history, Some(grandchild_id)),
                "for api-refactor",
            );
            assert_eq!(
                agent_view_back_button_label(history, Some(unnamed_mid_id)),
                "for Orchestrator",
            );
            assert_eq!(
                agent_view_back_button_label(history, Some(nested_under_unnamed_id)),
                "for parent agent",
            );
        });
    });
}

/// A child linked to its parent only via a legacy server conversation token
/// in `parent_agent_id` (no explicit parent conversation id, no run id) must
/// still resolve the parent through the history model's canonical
/// resolution, yielding the same back-button label as an id-linked child.
#[test]
fn back_button_label_resolves_token_only_parent_linkage() {
    App::test((), |mut app| async move {
        crate::test_util::settings::initialize_history_persistence_for_tests(&mut app);
        let terminal_view_id = EntityId::new();
        let history_model = app.add_singleton_model(|_| BlocklistAIHistoryModel::new_for_test());
        let child_id = history_model.update(&mut app, |history, ctx| {
            let root_id = history.start_new_conversation(terminal_view_id, false, false, ctx);
            history
                .set_server_conversation_token_for_conversation(root_id, "root-token".to_string());
            let child_id = history.start_new_conversation(terminal_view_id, false, false, ctx);
            history
                .conversation_mut(&child_id)
                .expect("child conversation exists")
                .set_parent_agent_id("root-token".to_string());
            child_id
        });

        history_model.read(&app, |history, _| {
            assert_eq!(
                agent_view_back_button_label(history, Some(child_id)),
                "for Orchestrator",
            );
        });
    });
}

/// #620: the git-status subscription tested for `GitDiffStats` specifically, so a
/// prompt configured with `GitBranchStatus` or `GithubPullRequest` and nothing else
/// got no subscription at all -- a git-backed chip with no source feeding it.
///
/// The pin gates on any of the three via `uses_git_status_chips`
/// (`42effe840:app/src/terminal/view.rs:5100`); this fork had never ported it.
///
/// SCOPE, stated honestly because the first version of this comment overclaimed:
/// this exercises `uses_git_status_chips` ONLY. It does not drive
/// `should_subscribe_to_git_status`, `needs_git_status_for_chip_ui` or
/// `needs_git_status_for_agent_context`, so it does not pin the widening in situ.
///
/// The claim it originally carried -- "reverting the fix turns this red" -- was
/// false. Reverting deletes `uses_git_status_chips`, so this stops COMPILING rather
/// than failing an assertion; and the regression that actually matters (restoring
/// the caller to `chips.contains(&ContextChipKind::GitDiffStats)` while leaving the
/// helper in place) leaves this green.
///
/// What it does buy: the arm list is the thing most likely to be edited by hand
/// later, and this fails loudly if a variant is dropped from it. The other two holes
/// #620 closed -- the CLI-agent-footer branch and the agent-context disjunct -- need
/// a `TerminalView` harness and remain uncovered; tracked in #620 rather than papered
/// over with a test that cannot fail.
#[cfg(feature = "local_fs")]
#[test]
fn git_status_chips_are_not_just_git_diff_stats() {
    // Each git-backed chip alone must be enough to warrant a subscription.
    assert!(
        TerminalView::uses_git_status_chips(vec![ContextChipKind::GitBranchStatus]),
        "GitBranchStatus alone is backed by git status (#620)"
    );
    assert!(
        TerminalView::uses_git_status_chips(vec![ContextChipKind::GithubPullRequest]),
        "GithubPullRequest alone is backed by git status (#620)"
    );
    assert!(TerminalView::uses_git_status_chips(vec![
        ContextChipKind::GitDiffStats
    ]));

    // Mixed with unrelated chips, the git-backed one still counts.
    assert!(TerminalView::uses_git_status_chips(vec![
        ContextChipKind::Time12,
        ContextChipKind::GitBranchStatus,
    ]));

    // Nothing git-backed: no subscription is warranted.
    assert!(!TerminalView::uses_git_status_chips(vec![
        ContextChipKind::Time12,
        ContextChipKind::Time24,
    ]));
    assert!(!TerminalView::uses_git_status_chips(vec![]));
}

